from itertools import product

def check(N, M):
    """Find all f: {1..N} -> {1..M} with f(f(n)) < f(n+1) for n=1..N-1.
    Note: f(f(n)) requires f(n) <= N so that f(f(n)) is defined.
    So we need f(n) in {1..N} for all n (image within domain)."""
    solutions = []
    for fvals in product(range(1, N+1), repeat=N):
        f = {i+1: fvals[i] for i in range(N)}
        ok = True
        for n in range(1, N):
            if f[f[n]] >= f[n+1]:
                ok = False
                break
        if ok:
            solutions.append(fvals)
    return solutions

for N in range(2, 8):
    sols = check(N, N)
    print(f"N={N}: {len(sols)} solutions")
    for s in sols[:10]:
        print("  ", s)
