from itertools import product

def check(N, M):
    """Find all f: {1..N} -> {1..M} with f(f(n)) < f(n+1) for n=1..N-1.
    f(f(n)) requires f(n) <= N."""
    solutions = []
    for fvals in product(range(1, M+1), repeat=N):
        f = {i+1: fvals[i] for i in range(N)}
        # check f(n) <= N for all n (so f(f(n)) is defined)
        if any(f[n] > N for n in range(1, N+1)):
            continue
        ok = True
        for n in range(1, N):
            if f[f[n]] >= f[n+1]:
                ok = False
                break
        if ok:
            solutions.append(fvals)
    return solutions

# Allow f(n) up to N+2 (larger codomain)
for N in range(2, 7):
    for extra in range(0, 3):
        M = N + extra
        sols = check(N, M)
        print(f"N={N}, M={M}: {len(sols)} solutions")
        for s in sols[:5]:
            print("  ", s)
    print()
